import { and, count, desc, eq, inArray, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, restorePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { ArchiveScope, IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted. Lookups and lists see only live
 * rows unless the caller passes `includeArchived` explicitly (the removal and
 * re-invite paths need the old row).
 */
function liveMemberPredicate(scope: ArchiveScope = {}) {
  return shouldFilterArchived(scope) ? isNull(members.archivedAt) : undefined;
}

/**
 * The (org, user) lookup behind every actor resolution. The pair is unique.
 * A removed membership is invisible here unless `scope` says otherwise.
 */
export async function findMember(
  orgId: OrgId,
  userId: UserId,
  scope: ArchiveScope = {},
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(scope),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
  scope: ArchiveScope = {},
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        liveMemberPredicate(scope),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/**
 * The subset of `userIds` that are current members of the org: live row and
 * active status. Anything absent from the returned set is not a member.
 */
export async function findCurrentMemberUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<string>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => row.userId));
}

